from z3 import *

X = [Int(f'x_{i}') for i in range(1, 17)]
s = Solver()

for x in X:
    s.add(x >= 0, x <= 3)

for j in range(4):
    s.add(Sum([If(X[i] == j, i + 1, 0) for i in range(16)]) == 34)

if s.check() == sat:
    m = s.model()
    print([m.evaluate(X[i]).as_long() for i in range(16)])
else:
    print("UNSAT")
